UPDATE t_ai_conversation
SET title       = #{title},
    consumption = #{consumption}, -- 总Token（历史+新Token）
    billing     = #{billing}      -- 总费用（历史+新费用）
WHERE ai_conversation_id = #{aiConversationId}
  AND user_id = #{userId}

